    private List<Vector2> AverageStroke(List<Vector2> first, List<Vector2> second, List<Vector2> third)
    {
        List<Vector2> normalizedFirst = GestureNormalizationHelper.ProcessPoints(first, 64, 250f);
        List<Vector2> normalizedSecond = GestureNormalizationHelper.ProcessPoints(second, 64, 250f);
        List<Vector2> normalizedThird = GestureNormalizationHelper.ProcessPoints(third, 64, 250f);
        int count = Mathf.Max(normalizedFirst.Count, Mathf.Max(normalizedSecond.Count, normalizedThird.Count));
        var averaged = new List<Vector2>(count);
        for (int i = 0; i < count; i++)
        {
            Vector2 firstPoint = i < normalizedFirst.Count ? normalizedFirst[i] : normalizedFirst[normalizedFirst.Count - 1];
            Vector2 secondPoint = i < normalizedSecond.Count ? normalizedSecond[i] : normalizedSecond[normalizedSecond.Count - 1];
            Vector2 thirdPoint = i < normalizedThird.Count ? normalizedThird[i] : normalizedThird[normalizedThird.Count - 1];
            averaged.Add((firstPoint + secondPoint + thirdPoint) / 3f);
        }
        return averaged;
    }
